import{z as i,x as B,o as l,c as m,q as p,j as r,D as e,d as t,s as n,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"交叉熵与极大似然","description":"","frontmatter":{"title":"交叉熵与极大似然","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cross-entropy-mle.md","filePath":"llm/cross-entropy-mle.md","lastUpdated":1791063341000}'),d={name:"llm/cross-entropy-mle.md"};function A(h,a,_,f,u,c){const E=B("Mermaid");return l(),m("div",null,[a[2]||(a[2]=p('<h1 id="交叉熵与极大似然" tabindex="-1">交叉熵与极大似然 <a class="header-anchor" href="#交叉熵与极大似然" aria-label="Permalink to &quot;交叉熵与极大似然&quot;">​</a></h1><div class="epigraph"><p>把模型的 softmax 输出当成类别分布，最小化交叉熵就是在做极大似然；标签的 one-hot 只是这条似然的写法。</p><footer>—— 据 Goodfellow, Bengio &amp; Courville, Deep Learning, 2016；Shannon, A Mathematical Theory of Communication, 1948 整理</footer></div><p><a href="/llm/softmax-numerics">Softmax 与数值稳定</a>把分数变成 \\(p\\)。本课不重写减最大值。缺口是：有了 \\(p\\)，如何给一次预测打一个可反传的标量损失。分类里这个标量是交叉熵，它与「标签类别的对数似然」是同一件事。本课只钉住这一等价，不展开下一词的时间展开，那是两课之后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(p\\) 落在单纯形上，仍可以离标签很远。需要一个损失，在 \\(p\\) 把质量都分给正确类时接近 \\(0\\)，在分给错误类时变大，并且对 \\(z\\) 可微。平方误差也能做，但它惩罚的是概率值本身，不直接对应「生成这条标签的概率」。统计上，若把标签视为从未知分布抽样，一次观测的似然就是 \\(p_y\\)。缺口是把 \\(-\\log p_y\\) 写成训练目标，并承认它就是交叉熵。</p><p><span class="marginnote">代入几个数感受 \\(-\\log p\\) 的「罚分」力度：正确类概率 \\(0.5\\) 时损失约 \\(0.69\\)，\\(0.9\\) 时约 \\(0.11\\)，\\(0.01\\) 时约 \\(4.6\\)。概率每往下跌一个数量级，损失就多涨约 \\(2.3\\)（nat）——压到接近零不是「多扣一点分」，而是指数级的重罚，这正是模型「越惊讶、罚越狠」的含义。</span></p><p>对经验分布 \\(\\hat q\\)（正确类为 \\(1\\)，其余为 \\(0\\)），交叉熵 \\(H(\\hat q,p)=-\\sum_k \\hat q_k\\log p_k\\) 只剩 \\(-\\log p_y\\)。KL 散度 \\(D_{\\mathrm{KL}}(\\hat q\\|p)=H(\\hat q,p)-H(\\hat q)\\)，而 one-hot 的熵为 \\(0\\)，故最小化交叉熵与最小化 KL 在分类里重合。本课不把 KL 当成另一门课的主角，只用来说明：我们不是在拟合分数，而是在拟合分布。</p><h3 id="交叉熵不是「概率差的绝对值」" tabindex="-1">交叉熵不是「概率差的绝对值」 <a class="header-anchor" href="#交叉熵不是「概率差的绝对值」" aria-label="Permalink to &quot;交叉熵不是「概率差的绝对值」&quot;">​</a></h3><p>\\(|1-p_y|\\) 在 \\(p_y\\) 已经是 \\(0.9\\) 时很小，但 \\(-\\log p_y\\) 仍在逼模型把质量继续堆到正确类上。更重要的是梯度：对 softmax 接交叉熵，\\(\\partial L/\\partial z=p-y\\)，错误类只要还有质量就会被往下推。改用 MAE 或 MSE 接在 softmax 后，梯度会被 \\(p(1-p)\\) 一类因子再压一层，饱和更严重。后课默认分类头接的是交叉熵，不是回归损失。</p><p><span class="marginnote">标签可以是 soft label，例如蒸馏里的教师分布。那时 \\(H(q,p)=-\\sum_k q_k\\log p_k\\) 不再退化成单项。本课的默认仍是 one-hot；软标签不改变「交叉熵 \\(=\\) 负对数似然」这条，只是似然换成了教师的。 </span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定分数 \\(z\\)、稳定 softmax 得到 \\(p\\)，整数标签 \\(y\\in\\{0,\\ldots,K-1\\}\\)，</p> \\[L=-\\log p_y= -z_y+\\log\\sum_k\\mathrm{e}^{z_k}. \\]<p>右端是 \\(\\mathrm{logsumexp}\\) 写法，下一课专门处理它的 underflow。形状上，\\(L\\) 对每个样本一个标量，再对批求平均。\\(y\\) 必须落在 \\(0\\ldots K-1\\)；越界不是 UNK，是标签协议错了。类别不平衡时可以对 \\(L\\) 按类加权，那是数据课的事，不改本课的定义。</p><p>与 logits 的梯度 \\(\\partial L/\\partial z=p-e_y\\) 应记住：正确类分量是 \\(p_y-1\\le 0\\)，其余是 \\(p_k\\ge 0\\)。无需再把 softmax 的 Jacobian 显式乘一遍。这是后课反向传播里「损失对最后一层的局部导数」的具体实例。</p>',15)),(l(),r(s,null,{default:e(()=>[n(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%88%86%E6%95%B0%20z%22%5D%20--%3E%20SM%5B%22%E7%A8%B3%E5%AE%9A%20softmax%22%5D%0A%20%20SM%20--%3E%20P%5B%22%E5%88%86%E5%B8%83%20p%22%5D%0A%20%20Y%5B%22%E6%A0%87%E7%AD%BE%20y%22%5D%20--%3E%20CE%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20P%20--%3E%20CE%0A%20%20CE%20--%3E%20L%5B%22%E6%A0%87%E9%87%8F%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[t("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"极大似然把「模型认为该标签有多可能」变成可加的目标：独立样本的联合似然是乘积，取负对数变成求和。这与信息论里用 \\(-\\log p\\) 度量「惊讶」一致：模型越意外，损失越大。平均交叉熵的单位是 nat（自然对数）或 bit（以 \\(2\\) 为底）；比较不同实验时底要一致，否则「损失从 \\(2.1\\) 降到 \\(1.8\\)」不可比。",-1)),a[5]||(a[5]=o("p",null,[o("span",{class:"marginnote"},"nat 和 bit 只是单位不同，像米和英尺：换底乘个常数即可，\\(1\\) nat \\(\\approx 1.44\\) bit。直觉上，一个「抛硬币级别的意外」（概率 \\(0.5\\) 的事件）按 \\(2\\) 为底算恰好是 \\(1\\) bit，按自然对数算就是 \\(0.693\\) nat。看到论文报「损失 2.1」，先确认它用的哪个底，再谈好坏。")],-1)),(l(),r(s,null,{default:e(()=>[n(E,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E6%A0%B7%E6%9C%AC%201%20%E7%9A%84%E4%BC%BC%E7%84%B6%20p1%22%5D%20--%3E%20PR%5B%22%E8%81%94%E5%90%88%E4%BC%BC%E7%84%B6%20%3D%20%E8%BF%9E%E4%B9%98%22%5D%0A%20%20S2%5B%22%E6%A0%B7%E6%9C%AC%202%20%E7%9A%84%E4%BC%BC%E7%84%B6%20p2%22%5D%20--%3E%20PR%0A%20%20PR%20--%3E%20U%5B%22%E7%9B%B4%E6%8E%A5%E8%BF%9E%E4%B9%98%EF%BC%9A%E5%87%A0%E7%99%BE%E4%B8%AA%E5%B0%8F%E4%BA%8E%201%20%E7%9A%84%E6%95%B0%E7%9B%B8%E4%B9%98%EF%BC%8C%E5%BE%88%E5%BF%AB%E4%B8%8B%E6%BA%A2%E4%B8%BA%200%22%5D%0A%20%20PR%20--%3E%20NEG%5B%22%E5%8F%96%E8%B4%9F%E5%AF%B9%E6%95%B0%22%5D%0A%20%20NEG%20--%3E%20SUM%5B%22%E6%8D%9F%E5%A4%B1%E5%8F%98%E6%B1%82%E5%92%8C%EF%BC%9A%E2%88%92log%20p1%20%2B%20%E2%88%92log%20p2%20%2B%20%E2%80%A6%22%5D%0A%20%20SUM%20--%3E%20AVG%5B%22%E5%AF%B9%E6%89%B9%E6%B1%82%E5%B9%B3%E5%9D%87%EF%BC%9A%E9%80%90%E6%A0%B7%E6%9C%AC%E5%8F%AF%E5%8A%A0%E3%80%81%E5%8F%AF%E6%AF%94%E8%BE%83%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=p('<p>因为 \\(L\\) 只通过 \\(p_y\\) 依赖正确类，错误类之间如何分剩余质量，在 one-hot 监督下不受直接约束。模型可以把剩余质量均匀摊开，也可以堆到某个相似类上。这不是缺陷，是目标的定义：我们只要求正确类的质量尽量大。若需要类间结构，要改标签或改损失，不能指望交叉熵自动学会。</p><p><span class="marginnote">初学者容易以为训练是在「惩罚错误类」，损失函数里应该有一项「错误类概率」。实际上 one-hot 交叉熵的公式里根本看不到错误类：它只含 \\(-\\log p_y\\) 一项，错误类只是通过 softmax 的归一化间接被压低。所以「猫狗二分类里模型把剩余概率押给狐狸还是狼」，监督信号完全不管。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理概率连乘导致的 underflow，那是下一课<a href="/llm/logspace-underflow">对数空间与 underflow</a>。也不把序列上的因式分解写开，那是<a href="/llm/clm-as-next-token">下一词分类</a>。回归、对比损失、强化学习里的策略梯度，都不在本课。后课默认：分类头的训练目标是平均交叉熵，对 logits 的梯度是 \\(p-y\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交叉熵 \\(L=-\\log p_y\\) 即标签的负对数似然；one-hot 下与 KL 只差一个常数 \\(0\\)。</li><li>对 softmax 的梯度是 \\(p-y\\)，不必再乘 Jacobian。</li><li>目标只约束正确类的质量；错误类之间的分配不受直接监督。</li><li>损失的底决定单位，跨实验比较时必须一致。</li><li>出处：Goodfellow et al., Deep Learning, 2016；Shannon, 1948。</li></ul>',6))])}const D=i(d,[["render",A]]);export{C as __pageData,D as default};
